/// 学習時と同じ正規化 + Linear(23→16) → ReLU → Linear(16→1) のforward pass。
/// 出力はlogit（Sigmoidではない）。呼び出し側は `clamp(-15, 15)` してから
/// `exp(logit)` として使う
/// 重み定数の入力次元。特徴量定義（OPP_MOVE_FEATURES）より小さい間は
/// **末尾の新特徴量を重み0として無視する**（= 再学習前は挙動不変。
/// gives_check 追加 2026-08-20 の移行用。再学習後に定数が26次元になれば一致する）
const NN_IN: usize = OPP_MOVE_NN_MEAN.len();

pub fn opp_move_nn_forward(
    features: &[f64; crate::opp_move_features::OPP_MOVE_FEATURES],
) -> f64 {
    #[cfg(feature = "effect-profile")]
    crate::effect_profile::bump(&crate::effect_profile::OPP_MOVE_NN);
    let mut x = [0.0f64; NN_IN];
    for i in 0..NN_IN {
        x[i] = (features[i] - OPP_MOVE_NN_MEAN[i]) / OPP_MOVE_NN_STD[i];
    }
    let mut h = [0.0f64; 16];
    for j in 0..16 {
        let mut s = OPP_MOVE_NN_B1[j];
        for i in 0..NN_IN {
            s += OPP_MOVE_NN_W1[j][i] * x[i];
        }
        h[j] = s.max(0.0); // ReLU
    }
    let mut out = OPP_MOVE_NN_B2;
    for j in 0..16 {
        out += OPP_MOVE_NN_W2[j] * h[j];
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    /// プレースホルダ（ゼロ重み = 全候補一様）のまま誤ってマージ・凍結する
    /// 事故のガード（codexレビュー指摘、2026-07-22）
    #[test]
    fn weights_are_not_placeholder_zeros() {
        assert!(
            OPP_MOVE_NN_W1.iter().flatten().any(|&w| w != 0.0),
            "W1が全ゼロ = export_opp_move_weights.py 未実行のプレースホルダ"
        );
        assert!(OPP_MOVE_NN_W2.iter().any(|&w| w != 0.0));
    }

    /// numpy側で同じ定数（このファイルのAUTO-GENERATED区間）を独立に読み直して
    /// 計算した値との突き合わせ（行列の転置・インデックス取り違えの検出用）。
    /// 期待値の再生成はscratchpadのcrosscheck.py相当（Rustソースから定数を
    /// パースしてforwardをnumpyで再計算）で行う
    #[test]
    fn matches_numpy_cross_check() {
        // 期待値の再生成: scratchpad の crosscheck.py 相当（このファイルの
        // 定数を numpy で読み直して forward を再計算）。26次元・gives_check
        // 込みの学習（2026-08-21、608局・seed3 = 4シードのオフライン検証で
        // m020/m026/m028/m147 の合計が最良）で再生成した
        let mut pawn_push = [0.0f64; 26];
        pawn_push[0] = 1.0; // advance
        pawn_push[13] = 1.0; // moved_pawn
        pawn_push[21] = 1.0; // move_dist
        pawn_push[22] = 1.0; // from_home
        let mut bishop_probe = [0.0f64; 26];
        bishop_probe[0] = 3.0; // advance
        bishop_probe[4] = 1.0; // threat_known
        bishop_probe[12] = 2.0; // opp_foul_count_this_turn
        bishop_probe[18] = 1.0; // moved_bishop
        bishop_probe[21] = 6.0; // move_dist
        bishop_probe[22] = 1.0; // from_home
        bishop_probe[23] = 2.0; // my_foul_count_last_turn
        let mut en_prise_escape = [0.0f64; 26];
        en_prise_escape[0] = 1.0; // advance
        en_prise_escape[18] = 1.0; // moved_bishop
        en_prise_escape[21] = 3.0; // move_dist
        en_prise_escape[24] = 1.0; // en_prise_flee
        let mut check_knight_drop = [0.0f64; 26];
        check_knight_drop[3] = 1.0; // is_drop
        check_knight_drop[15] = 1.0; // moved_knight
        check_knight_drop[25] = 1.0; // gives_check
        let cases: [([f64; 26], f64); 5] = [
            ([0.0; 26], -0.6313554551377111),
            (pawn_push, -0.717242036076476),
            (bishop_probe, -3.4407549160198565),
            (en_prise_escape, -1.0486525962639086),
            (check_knight_drop, 1.6008489324555826),
        ];
        for (features, expected) in cases {
            let got = opp_move_nn_forward(&features);
            assert!(
                (got - expected).abs() < 1e-9,
                "features={features:?} got={got} expected={expected}"
            );
        }
    }

    /// opp_move_weight は1手の意思決定あたり最大10万回超のオーダーで
    /// 呼ばれる（粒子再生成時はさらに増える）。ONNX等の推論クレートを
    /// 避けて手書きforward passにした前提が崩れていないかのガード
    /// （数百FLOPのはずが将来誤って重くなったら検出する）
    #[test]
    fn forward_pass_is_fast_enough_for_hot_loop() {
        let mut features = [0.0f64; 26];
        features[0] = 1.0;
        features[4] = 1.0;
        features[9] = 1.0;
        let n = 1_000_000;
        let start = std::time::Instant::now();
        let mut acc = 0.0f64;
        for _ in 0..n {
            acc += opp_move_nn_forward(&std::hint::black_box(features));
        }
        let elapsed = start.elapsed();
        std::hint::black_box(acc);
        eprintln!("{n}回のforward pass: {elapsed:?}（1回あたり{:?}）", elapsed / n);
        // release実測は100ns未満、debug実測は十数us/回のオーダー。
        // CI環境のノイズでflakyにならないようdebugだけ閾値を緩める
        let threshold = if cfg!(debug_assertions) { 1e-4 } else { 1e-5 };
        assert!(
            elapsed.as_secs_f64() / f64::from(n) < threshold,
            "forward passが遅すぎる: {elapsed:?} / {n}回"
        );
    }
}
